import sys
from collections import deque

def main():
    data = sys.stdin.read().splitlines()
    idx = 0
    if not data[idx]:
        idx += 1
    n = int(data[idx].strip())
    idx += 1

    file_names = data[idx].strip().split()
    idx += 1

    name_to_idx = {name: i for i, name in enumerate(file_names)}
    adj = [[] for _ in range(n)]

    for _ in range(n):
        parts = data[idx].strip().split()
        idx += 1
        file_name = parts[0]
        k = int(parts[1])
        u = name_to_idx[file_name]

        for _ in range(k):
            line = data[idx].strip()
            idx += 1
            if line.startswith("import"):
                deps_part = line[6:]
                dep_names = [x.strip() for x in deps_part.split(",")]
                for dep_name in dep_names:
                    if dep_name in name_to_idx:
                        v = name_to_idx[dep_name]
                        adj[u].append(v)

    best_cycle = None
    best_len = float('inf')

    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        q = deque([start])
        dist[start] = 0

        while q:
            u = q.popleft()
            if dist[u] >= best_len - 1:
                continue

            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v == start:
                    cycle_len = dist[u] + 1
                    if cycle_len < best_len:
                        path = []
                        curr = u
                        while curr != start:
                            path.append(curr)
                            curr = parent[curr]
                        path.append(start)
                        path.reverse()
                        best_cycle = path
                        best_len = cycle_len
                elif dist[v] <= dist[u]:
                    pass

    if best_cycle is None:
        print("SHIP IT")
    else:
        cycle_names = [file_names[i] for i in best_cycle]
        print(" ".join(cycle_names))

if __name__ == "__main__":
    main()
